// Data of the featured case levels.
// - Case list and texts: data/cases_index.json (bundled; the backend does not serve it).
// - Series: data/cache/case_<id>_<VAR>.json, first from the backend (/api/cases/<file id>, same as
//   src/shared/api.ts), and from the bundled files when the backend is not running (offline, rule 10).
import { fetchCase } from '../shared/api'
import type { CaseData } from '../shared/contract'

/** One entry of data/cases_index.json (generated by pipeline/build_cases.py). */
export interface CaseIndexEntry {
  id: string
  title: string
  place: string
  lat: number
  lon: number
  /** Shown to the player first */
  question: string
  /** Shown below the question */
  context: string
  /** Repo paths of the case files, e.g. "data/cache/case_dana_valencia_T2M.json" */
  files: string[]
  /** Plain-English statistical facts per variable (for the AI checker); never shown before the answer */
  facts: Record<string, string>
}

const indexModules = import.meta.glob<CaseIndexEntry[]>('../../data/cases_index.json', {
  eager: true,
  import: 'default',
})
const localCaseFiles = import.meta.glob<CaseData>('../../data/cache/case_*.json', { import: 'default' })

export const CASES: CaseIndexEntry[] = Object.values(indexModules)[0] ?? []

export function getCaseEntry(caseId: string): CaseIndexEntry | undefined {
  return CASES.find((c) => c.id === caseId)
}

/** "data/cache/case_dana_valencia_T2M.json" -> "case_dana_valencia_T2M" (the backend id). */
export function fileId(file: string): string {
  return file.split('/').pop()!.replace(/\.json$/, '')
}

/** "data/cache/case_dana_valencia_T2M.json" -> "T2M". */
export function fileVariable(file: string): string {
  return fileId(file).split('_').pop()!
}

async function loadLocal(file: string): Promise<CaseData> {
  const load = localCaseFiles[`../../${file}`]
  if (!load) throw new Error(`case file not found: ${file}`)
  return load()
}

/** One case series in the contract format: backend first, bundled file as fallback. */
export async function loadCaseFile(file: string, signal?: AbortSignal): Promise<CaseData> {
  try {
    return await fetchCase(fileId(file), signal)
  } catch (err) {
    if (signal?.aborted) throw err
    return loadLocal(file)
  }
}
